mapper.select:
-- select distinct mt.id, mt.user_id, mt.code, mt.name, mt.owner, mt.seller, mt.buyer, mt.liaison, mt.phone, mt.area, -- mt.address, mt.status, mt.enabled, mt.tenant, mt.deleted, mt.create_by, -- mt.create_time, mt.update_by, mt.update_time -- from `merchant` mt -- left join `vip_card` vcd on vcd.merchant_id = mt.id select vcd.id, vcd.supplier_id,vcd.code from meattrade_vip_card vcd
vcd.supplier_id in
#{supplierId}
or vcd.code like concat('%', #{param.keyword}, '%')
and vcd.tenant = #{param.tenant}

select dt.id, dt.short_id, dt.user_id, dt.supplier_id, dt.mode, dt.amount, dt.status, dt.complete_time,
dt.tenant, dt.deleted, dt.create_by, dt.create_time, dt.update_by, dt.update_time
from `meattrade_deposit` dt


        dt.create_time >= #{param.period.begin}


        and dt.create_time <= #{param.period.end}



            and dt.supplier_id in

                #{supplierId}



            or (
                dt.id = #{id} or dt.short_id = #{id}
            )



        and dt.status = #{param.status.name}

    and dt.tenant = #{param.tenant}

order by dt.create_time desc
